-- Ejecutar por Sebastián. No reclasifica documentos ni cambia importes del P&L.
begin;
set local lock_timeout='5s';
create table public.contabilidad_catalogo (
 rfc text not null references public.razones_sociales(rfc),codigo text not null,nombre text not null,
 nivel integer not null,capturable boolean not null,rubro text,fuente text not null,fila integer not null,
 primary key(rfc,codigo)
);
-- INICIO SEMILLA GENERADA
-- FIN SEMILLA GENERADA
create table public.contabilidad_asignaciones (
 id uuid primary key,clave text not null,revision integer not null check(revision>0),
 rfc text not null,codigo text,anterior uuid references public.contabilidad_asignaciones(id),
 huella text not null,origen jsonb not null,motivo text not null check(length(trim(motivo)) between 12 and 1000),
 solicitud jsonb not null,autor uuid not null references public.perfiles(id),autor_nombre text not null,
 creado_en timestamptz not null default now(),unique(clave,revision),
 foreign key(rfc,codigo) references public.contabilidad_catalogo(rfc,codigo)
);
alter table public.contabilidad_catalogo enable row level security;
alter table public.contabilidad_asignaciones enable row level security;
revoke all on public.contabilidad_catalogo,public.contabilidad_asignaciones from public,anon,authenticated;
grant select on public.contabilidad_catalogo,public.contabilidad_asignaciones to authenticated;
create policy catalogo_finanzas on public.contabilidad_catalogo for select to authenticated using((select public.ve_finanzas()));
create policy asignaciones_finanzas on public.contabilidad_asignaciones for select to authenticated using((select public.ve_finanzas()));

-- Fuente viva: una fila por concepto; la cabecera solo cuando no existen conceptos.
-- Huella de las filas originales: al cambiar razón social, sucursal, cobertura, estado o importe se exige revisar.
create view public.contabilidad_movimientos with(security_invoker=true) as
 select * from (select 'concepto:'||c.id::text as clave,f.fecha_emision as fecha,f.id as factura_id,f.sucursal_id,
 f.rfc_receptor as rfc,f.nombre_emisor||' · '||coalesce(f.serie,'')||coalesce(f.folio,'')||' · '||c.descripcion as descripcion,
 coalesce(c.cuenta_pl,f.cuenta_pl) as categoria,c.importe as importe,
 md5(jsonb_build_array(to_jsonb(f),to_jsonb(c))::text) as huella,
 coalesce(f.cubre_desde,f.fecha_emision) as cubre_desde,coalesce(f.cubre_hasta,f.fecha_emision) as cubre_hasta
 from public.factura_conceptos c join public.facturas f on f.id=c.factura_id
 where f.estado::text<>'cancelada' and f.sustituido_por is null
 union all
 select 'factura:'||f.id::text,f.fecha_emision,f.id,f.sucursal_id,f.rfc_receptor,
 f.nombre_emisor||' · '||coalesce(f.serie,'')||coalesce(f.folio,''),f.cuenta_pl,f.subtotal-f.descuento,md5(to_jsonb(f)::text),coalesce(f.cubre_desde,f.fecha_emision),coalesce(f.cubre_hasta,f.fecha_emision)
 from public.facturas f where f.estado::text<>'cancelada' and f.sustituido_por is null
 and not exists(select 1 from public.factura_conceptos c where c.factura_id=f.id)
 union all
 select 'gasto:'||g.id::text,g.fecha,null::uuid,g.sucursal_id,null::text,g.concepto,g.cuenta_pl,g.monto,md5(to_jsonb(g)::text),g.fecha,g.fecha
 from public.gastos_caja_chica g where g.anulado_en is null
 union all
 select 'ajuste:'||g.id::text,g.mes,null::uuid,g.sucursal_id,null::text,g.concepto,g.cuenta,g.monto,md5(to_jsonb(g)::text),g.mes,(g.mes+interval '1 month'-interval '1 day')::date
 from public.gastos_mes g) m where (select public.ve_finanzas());
revoke all on public.contabilidad_movimientos from public,anon,authenticated;
grant select on public.contabilidad_movimientos to authenticated;
create view public.contabilidad_actual with(security_invoker=true) as
 select distinct on(clave) id,clave,revision,rfc,codigo,huella,motivo,autor_nombre,creado_en
 from public.contabilidad_asignaciones order by clave,revision desc;
revoke all on public.contabilidad_actual from public,anon,authenticated;
grant select on public.contabilidad_actual to authenticated;

create schema if not exists contabilidad_privada;
revoke all on schema contabilidad_privada from public,anon;
grant usage on schema contabilidad_privada to authenticated;
-- Escritura exclusivamente mediante función, para que usuario/historial/versión sean atómicos.
create function contabilidad_privada.asignar(p_id uuid,p_clave text,p_anterior uuid,p_huella text,p_rfc text,p_codigo text,p_motivo text,p_confirmar boolean)
returns uuid language plpgsql security definer set search_path='' as $asignacion$
declare v_sol jsonb;v_previa public.contabilidad_asignaciones;v_actual public.contabilidad_asignaciones;
 v_mov public.contabilidad_movimientos;v_cuenta public.contabilidad_catalogo;v_nombre text;
begin
 if auth.uid() is null or not exists(select 1 from public.perfiles p where p.id=auth.uid() and p.rol::text='admin' and p.activo and not p.debe_cambiar_contrasena) then raise exception 'Solo administración asigna cuentas.';end if;
 if p_id is null or p_clave is null or p_huella is null or p_rfc is null or p_confirmar is distinct from true or coalesce(length(trim(p_motivo)),0) not between 12 and 1000 then raise exception 'Revisa la equivalencia y confirma con un motivo específico.';end if;
 v_sol:=jsonb_build_array(p_clave,p_anterior,p_huella,p_rfc,p_codigo,p_motivo,p_confirmar);
 perform pg_advisory_xact_lock(hashtextextended('contabilidad-solicitud:'||p_id,0));
 select * into v_previa from public.contabilidad_asignaciones a where a.id=p_id;
 if found then
  if v_previa.autor<>auth.uid() or v_previa.solicitud is distinct from v_sol then raise exception 'Solicitud ya utilizada con otros datos.';end if;
  return v_previa.id;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('contabilidad-clave:'||p_clave,0));
 -- Bloquear la fuente antes de releer la vista (incluye cabecera y conceptos).
 if p_clave like 'concepto:%' then
  perform 1 from public.facturas f join public.factura_conceptos c on c.factura_id=f.id where c.id::text=substring(p_clave from 10) for update of f;
  perform 1 from public.factura_conceptos c where c.id::text=substring(p_clave from 10) for update;
 elsif p_clave like 'factura:%' then
  perform 1 from public.facturas f where f.id::text=substring(p_clave from 9) for update;
 elsif p_clave like 'gasto:%' then
  perform 1 from public.gastos_caja_chica g where g.id::text=substring(p_clave from 7) for update;
 elsif p_clave like 'ajuste:%' then
  perform 1 from public.gastos_mes g where g.id::text=substring(p_clave from 8) for update;
 else raise exception 'Origen no permitido.';end if;
 select * into v_mov from public.contabilidad_movimientos m where m.clave=p_clave;
 if not found or v_mov.huella is distinct from p_huella then raise exception 'El documento cambió o ya no está vigente; revisa nuevamente.';end if;
 select * into v_actual from public.contabilidad_asignaciones a where a.clave=p_clave order by a.revision desc limit 1;
 if v_actual.id is distinct from p_anterior then raise exception 'La asignación cambió; vuelve a revisar.';end if;
 if v_mov.rfc is not null and v_mov.rfc<>p_rfc then raise exception 'Conserva la razón social del documento.';end if;
 if not exists(select 1 from public.razones_sociales r where r.rfc=p_rfc and r.activa) or
 (v_mov.sucursal_id is not null and not exists(select 1 from public.razon_social_sucursales rs where rs.rfc=p_rfc and rs.sucursal_id=v_mov.sucursal_id)) then raise exception 'Razón social o sucursal no autorizada.';end if;
 if p_codigo is not null then
  select * into v_cuenta from public.contabilidad_catalogo c where c.rfc=p_rfc and c.codigo=p_codigo;
  if not found or not v_cuenta.capturable then raise exception 'Elige una cuenta capturable de esta razón social.';end if;
  -- Proteger memo y oficina: no convertir compras en gasto ni oficina en sucursal.
  if (v_mov.categoria='insumos' and p_codigo not like '502-%') or
   (v_mov.categoria='inversiones' and p_codigo not similar to '(15[0-9]|17[0-9])-%') or
   (coalesce(v_mov.categoria,'otros') not in ('insumos','inversiones') and
    ((v_mov.sucursal_id is null and p_codigo not like '603-%') or (v_mov.sucursal_id is not null and p_codigo not like '602-%'))) then raise exception 'La cuenta cruza memo, gasto de tienda u oficina. Revisa primero la categoría del origen.';end if;
 end if;
 if v_actual.id is not null and v_actual.codigo is not distinct from p_codigo and v_actual.rfc=p_rfc and v_actual.huella=p_huella then return v_actual.id;end if;
 select p.nombre into v_nombre from public.perfiles p where p.id=auth.uid();
 values(p_id,p_clave,coalesce(v_actual.revision,0)+1,p_rfc,p_codigo,v_actual.id,p_huella,to_jsonb(v_mov),trim(p_motivo),v_sol,auth.uid(),v_nombre);
 return p_id;
end $asignacion$;
revoke all on function contabilidad_privada.asignar(uuid,text,uuid,text,text,text,text,boolean) from public,anon,authenticated;
grant execute on function contabilidad_privada.asignar(uuid,text,uuid,text,text,text,text,boolean) to authenticated;
create function public.asignar_cuenta_contable(p_id uuid,p_clave text,p_anterior uuid,p_huella text,p_rfc text,p_codigo text,p_motivo text,p_confirmar boolean)
returns uuid language sql security invoker set search_path='' as $$
 select contabilidad_privada.asignar(p_id,p_clave,p_anterior,p_huella,p_rfc,p_codigo,p_motivo,p_confirmar)
$$;
revoke all on function public.asignar_cuenta_contable(uuid,text,uuid,text,text,text,text,boolean) from public,anon,authenticated;
grant execute on function public.asignar_cuenta_contable(uuid,text,uuid,text,text,text,text,boolean) to authenticated;
commit;
